using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws;

internal sealed class RarePriorResidentCodeDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/RarePriorResidentCode.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "RarePriorResidentCode", H("RarePriorResidentCode"), Blocks(
                Paragraph(Text("Explicit mixed-radix codecs encode NativeControl, Registers, ThirdSnapshot, FiniteFields, the saturating monitor and one-shot mode. Their runtime has 793800 times 6023 times 4 addresses. A second explicit codec encodes the threshold tag, PC, bit position, candidate and output. Native dictionaries store every runtime-operation key and its original partial successor; service dictionaries store every service-bit key and microstep successor. A third resident dictionary initializes the threshold tag from the original finite query mode, using high for G, low for Gbeta and ordinary otherwise.")),
                Paragraph(Text("Resident code includes all three addressed key and payload tapes, the instruction records, and the saturation, threshold, acceptance and bit-width constants. The interpreter scans key bits sequentially and copies payload bits sequentially. Its row address, bit cursor, accumulator, PC and equality flag have fixed finite bounds. At the selected row, the exact copied payload implements the original runtimeStep or fair-bit microStep. The execution iteration count belongs to the correctness proof and is absent from runtime state.")),
                Paragraph(Text("The complete snapshot serializes ready and synthetic-copy runtimes, service state, current operation, 32 bounded output scratch cells, cursor, PC, table/source/destination addresses, bit position, matching flag and workspace. Fixed-width blocks make this encoding injective. B0 is one fixed witness greater than resident-code length plus complete snapshot width, with B0 at least one; it is independent of prior, horizon and rare mass. All scanner states fit the same snapshot fields. The scratch is a finite output workspace; full-record rendering is supplied separately.")),
                Node("bit-code-length", "bit_code_length", "Unary block width", "Every finite address has the same fixed unary block width, including zero. The serial scanner controller uses this supplier to charge its complete local state."),
                Node("bit-code-injective", "bit_code_injective", "Unary block recovery", "The unary block retains every finite address. The serial controller consumes this supplier in its complete local-state encoding."),
                Node("charged-snapshot-bound", "charged_snapshot_bound", "charged snapshot bound", "Each serialized field has fixed width. The budget is one plus resident width plus snapshot width and charges every stored tape and snapshot bit."),
                Node("complete-snapshot-encoding", "complete_snapshot_encoding", "complete snapshot encoding", "Fixed-width block boundaries recover every scalar field. Sequential recovery of the output blocks recovers the entire bounded output store."),
                Node("bounded-scanner-correct", "bounded_scanner_correct", "bounded scanner correct", "The scanner skips unmatched key rows, reaches the queried row and copies its unary payload bit by bit into the bounded accumulator."),
                Node("installed-bounded-program", "installed_bounded_program", "installed bounded program", "The three proved resident row relations implement original runtime updates, service microsteps and mode-based service initialization. Every scanner state has an injective charged snapshot encoding, and terminal permissions remain original."))));

    private static DocumentBlock.Describe Node(string id, string name, string title, string body) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + name), H(title),
            StatementSource.FromAuthor(Disp(Statement(name))), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(body))), DescribeRole.Theorem);

