    {
        "bit_code_length" => Seq(Forall, Sp, Open, Name("n"), Sp, Colon, Sp,
            Seq(Mathbb, Grp(F.Id("N"))), Close, Sp, Comma, Sp,
            Forall, Sp, Open, Name("x"), Sp, Colon, Sp, Name("Fin"), Sp, Name("n"), Close, Sp, Comma, Sp,
