        "installed_bounded_program" => Seq(Forall, Sp, Open, Sp, Name("z"), Sp, Colon, Sp, Name("Runtime"), Sp, Close, Sp, Comma, Sp, Open, Sp, Forall, Sp, Open, Sp, Name("op"), Sp, Colon, Sp, Name("Operation"), Sp, Close, Sp, Comma, Sp, Open, Sp, Forall, Sp, Open, Sp, Name("s"), Sp, Colon, Sp, Name("Service"), Sp, Close, Sp, Comma, Sp, Open, Sp, Forall, Sp, Open, Sp, Name("b"), Sp, Colon, Sp, Name("Letter"), Sp, Close, Sp, Comma, Sp, Open, Sp, Forall, Sp, Open, Sp, Name("base"), Sp, Colon, Sp, Name("MicroSnapshot"), Sp, Close, Sp, Comma, Sp, Open, Sp, Name("nativeProgram"), Sp, Name("z"), Sp, Name("op"), Sp, Eq, Sp, Name("runtimeStep"), Sp, Name("z"), Sp, Name("op"), Sp, Land, Sp, Name("serviceProgram"), Sp, Name("s"), Sp, Name("b"), Sp, Eq, Sp, Name("some"), Sp, Open, Sp, Name("microStep"), Sp, Name("s"), Sp, Name("b"), Sp, Close, Sp, Land, Sp, Name("initializationProgram"), Sp, Name("z"), Sp, Eq, Sp, Name("some"), Sp, Open, Sp, Name("entry"), Sp, Open, Sp, Name("selectedThreshold"), Sp, Name("z"), Sp, Close, Sp, Close, Sp, Land, Sp, Open, Sp, Forall, Sp, Open, Sp, Name("k"), Sp, Name("n"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Sp, Close, Sp, Open, Sp, Name("hk"), Sp, Colon, Sp, Name("k"), Sp, Leq, Sp, Name("runtimeSize"), Sp, Star, Sp, D(4), Sp, Close, Sp, Open, Sp, Name("hn"), Sp, Colon, Sp, Name("n"), Sp, Leq, Sp, Name("runtimeSize"), Sp, Plus, Sp, D(1), Sp, Close, Sp, Open, Sp, Name("q"), Sp, Colon, Sp, Name("Scanner"), Sp, Name("k"), Sp, Name("n"), Sp, Close, Sp, Comma, Sp, Name("residentCode"), Sp, Dot, Sp, Name("length"), Sp, Plus, Sp, Open, Sp, Name("snapshotCode"), Sp, Open, Sp, Name("scannerSnapshot"), Sp, Name("base"), Sp, Name("q"), Sp, Name("hk"), Sp, Name("hn"), Sp, Close, Sp, Close, Sp, Dot, Sp, Name("length"), Sp, Lt, Sp, Seq(Name("B"), D(0)), Sp, Close, Sp, Land, Sp, Open, Sp, Forall, Sp, Open, Sp, Name("k"), Sp, Name("n"), Sp, Colon, Sp, Seq(Mathbb, Grp(F.Id("N"))), Sp, Close, Sp, Open, Sp, Name("hk"), Sp, Colon, Sp, Name("k"), Sp, Leq, Sp,